  }

  async asignarAnalista(muestraId: number, analistaId: number, rol: string) {
    const muestra = await this.muestras.findOneBy({ id: muestraId });
    const analista = await this.analistas.findOneBy({ id: analistaId });
    if (!muestra || !analista) {
